package dev.manadj.library.group

import org.json.JSONObject
import kotlin.test.*

class GroupWireTest {
    // Backend af88644f static vector: no expected signature generated by this test.
    private val ack = """{"format":"manadj-device-group/v1","group_id":"33333333-3333-4333-8333-333333333333","kind":"ack","operation_id":"44444444-4444-4444-8444-444444444444","operation_sha256":"bd07374ead5d5044bb6495ecb706ebeb1dcf458314b4dc5b82df325b0ea2ebab","origin_device_id":"22222222-2222-4222-8222-222222222222","recipient_device_id":"11111111-1111-4111-8111-111111111111"}"""
    @Test fun backendSignedAckVerifiesAndNativeSignerMatchesExactBytes() {
        val publicKey = GroupWire.decode64("Kay64UG8yvCyLhqU000LxzYeUm0L/hLIl5S8kyKWbdc=", 32)
        val signature = "pRNysV6X5fXFK167ficwXbYSdgvsk8iDQD/KeURZKWNn7c97uhbDSFKLRrVZsKFSa9L4hwACjcgErWG59huaCA=="
        val signed = GroupSigned(GroupWire.encode64(ack.toByteArray()), signature)
        val verified = GroupWire.verify(signed, publicKey)
        assertEquals("fdf44f26c8e2a4906d4807fa4994760e86be2ca9af2be63d90a77c236e1c837b", verified.sha256)
        val seed = ByteArray(32) { (it + 32).toByte() }
        assertEquals(signed, GroupWire.sign(JSONObject(ack), seed))
        assertFails { GroupWire.verify(signed.copy(bodyBase64 = GroupWire.encode64(ack.replace("ack", "bad").toByteArray())), publicKey) }
    }

    @Test fun canonicalFramingRejectsDuplicatesLooseJsonInvalidUtf8AndOversizeBeforeTrust() {
        assertFails { GroupWire.parse("""{"a":null,"a":1}""".toByteArray()) }
        assertFails { GroupWire.parse("""{a:1}""".toByteArray()) }
        assertFails { GroupWire.parse("""{"a": 1}""".toByteArray()) }
        assertFails { GroupWire.parse(byteArrayOf(0xc3.toByte(), 0x28)) }
        assertFails { GroupWire.parse(("[".repeat(25) + "0" + "]".repeat(25)).toByteArray()) }
        assertFails { GroupWire.decode64("AA", 64) } // missing canonical padding
        assertFails { GroupWire.decode64("A".repeat(GroupWire.MAX_BODY * 2), GroupWire.MAX_BODY) }
        assertFails { GroupSigned.parse(JSONObject("""{"body_b64":"e30=","signature_b64":"bad","members":[]}""")) }
    }
}
